const assert=require('node:assert/strict');
const d=globalThis.CWPArticleDrafts;
const field=(name,value,type='text',key)=>({name,value,type,checked:false,dataset:key?{draftKey:key}:{}});
const parent={article:'a',revision:'1',hash:'h1',purpose:'save'};
const text=field('block_text','旧正文','textarea','block-a:text');
const checkbox=field('block_material_0','material-a','checkbox','block-a:material:material-a');checkbox.checked=true;
const csrf=field('_csrf','old-csrf','hidden');
const form={elements:[text,checkbox,csrf]};
const draft=d.capture(form,parent);
assert.equal(Object.keys(draft.fields).length,2);
const reorderedText=field('block_text','新默认','textarea','block-a:text');
const reorderedCheckbox=field('block_material_4','material-a','checkbox','block-a:material:material-a');
const newChoice=field('block_material_4','material-b','checkbox','block-a:material:material-b');
const currentCSRF=field('_csrf','fresh-csrf','hidden');
let result=d.restore({elements:[currentCSRF,newChoice,reorderedCheckbox,reorderedText]},draft,parent);
assert.equal(reorderedText.value,'旧正文');assert.equal(reorderedCheckbox.checked,true);assert.equal(newChoice.checked,false);assert.equal(currentCSRF.value,'fresh-csrf');assert.equal(result.matched,2);
reorderedText.value='新稿正文';
result=d.restore({elements:[reorderedText]},draft,{...parent,revision:'2',hash:'h2'});
assert.equal(result.conflict,true);assert.equal(reorderedText.value,'新稿正文');
result=d.restore({elements:[reorderedText]},draft,{...parent,revision:'2',hash:'h2'},true);
assert.equal(reorderedText.value,'旧正文');assert.ok(result.missing.includes('block-a:material:material-a'));
const retained=d.capture({elements:[reorderedText]},parent,draft);
assert.equal(retained.fields['block-a:material:material-a'].checked,true);
assert.equal(d.restore(form,[{i:0,value:'legacy'}],parent).legacy,true);
const multi=field('choices','','select-multiple');multi.options=[{value:'a',selected:true},{value:'b',selected:false}];
const multiDraft=d.capture({elements:[multi]},parent);multi.options=[{value:'b',selected:true},{value:'a',selected:false}];
d.restore({elements:[multi]},multiDraft,parent);assert.equal(multi.options[1].selected,true);assert.equal(multi.options[0].selected,false);
const radioA=field('direction','a','radio'),radioB=field('direction','b','radio');radioB.checked=true;
const radioDraft=d.capture({elements:[radioA,radioB]},parent);radioA.checked=true;radioB.checked=false;
d.restore({elements:[radioB,radioA]},radioDraft,parent);assert.equal(radioB.checked,true);assert.equal(radioA.checked,false);
assert.equal(d.controls({elements:[field('ambiguous','a'),field('ambiguous','b')]}).length,0);
console.log('article draft identity, conflicts, missing materials and field semantics passed');
